const receipt={schema:'kenigevents.penpot-visual-executor-receipt.v1',generation:10,run_id:null,lease_identity:null,capsule:{semantic_identity:CAPSULE.semantic_identity,revision:CAPSULE.revision},control:CAPSULE.control,accepted_bundle:CAPSULE.accepted_bundle,input_hashes:CAPSULE.inputs,adapter:{identity:'ordinary-penpot-globals',version:String(penpot.version||'unknown'),primitives:{penpot:REQUIRED_PENPOT,penpotUtils:REQUIRED_UTILS}},pre_write_checks:[],operations:[],created:[],reused:[],replaced:[],evidence_roots:[],case_roots:[],group_roots:[],component_lineage:[],completed_mutations:[],rolled_back_mutations:[],unreverted_mutations:[],terminal_state:'PREFLIGHT'};
